static float[] Basis(float t,int n,bool periodic){float u=periodic?Mathf.Repeat(t,1)*n:Mathf.Clamp01(t)*(n-1);int i=Mathf.FloorToInt(u);float f=u-i;var b=new float[n];var w=new[]{Mathf.Pow(1-f,3)/6,(3*f*f*f-6*f*f+4)/6,(-3*f*f*f+3*f*f+3*f+1)/6,f*f*f/6};for(int k=0;k<4;k++){int j=i+k-1;j=periodic?(j%n+n)%n:Mathf.Clamp(j,0,n-1);b[j]+=w[k];}return b;}
